// Check GCal CREATE result - idempotency aware (finding #16, #17)
// Handles crash-and-retry scenario:
//   IF crash occurred after GCal CREATE but before DB SUCCESS update:
//     - This retry will create a DUPLICATE event (undesired)
//     - Prevention: idempotencyKey embedded in event description
//     - Recovery: if we see appointment already has calendar_event_id, treat as SUCCESS
//
// The definitive idempotency guarantee:
//   claim_integration_operations() pre-checks: if appointment already has
//   calendar_event_id, it marks the PENDING operation as SUCCESS before claiming.
//   So we would never even reach this node for an already-synced appointment.
//   This node handles the remaining case: GCal CREATE was called, result returned.

const result = $input.first()?.json || {};
let opCtx = {};

try {
    const claimItems = $('Postgres_Claim_Pending_Ops').all();
    const pi = $input.first()?.pairedItem;
    const piIdx = (pi && typeof pi.item === 'number') ? pi.item : (typeof pi === 'number' ? pi : 0);
    const routeItems = $('Route_Operation_Type').all();
    const prepItems = $('Prepare_GCal_Create_Idempotent').all();
    if (prepItems[piIdx]) {
        opCtx = prepItems[piIdx]?.json || claimItems[0]?.json || {};
    } else {
        opCtx = claimItems[0]?.json || {};
    }
} catch(e) {
    opCtx = $('Postgres_Claim_Pending_Ops').first()?.json || {};
}

const success = Boolean(
    result.id &&
    typeof result.id === 'string' &&
    !result.error &&
    !(result.statusCode >= 400)
);

const gcalEventId = success ? (result.id || null) : null;
const errorDetail = result.error
    ? JSON.stringify(result.error)
    : ((result.statusCode >= 400) ? 'HTTP_' + result.statusCode : null);

// If already_synced: GCal create succeeded but DB not yet updated
// (recovery case: pre-claim check would have caught this, but belt-and-suspenders)
const alreadySynced = Boolean(opCtx.calendar_event_id && opCtx.calendar_event_id !== '');

return [{
    json: {
        operation_id: opCtx.operation_id,
        appointment_id: opCtx.appointment_id,
        operation_type: opCtx.operation_type,
        attempt_count: opCtx.attempt_count,
        max_attempts: opCtx.max_attempts,
        calendar_event_id: opCtx.calendar_event_id,
        idempotency_key: opCtx.idempotency_key,
        success: success || alreadySynced,
        gcal_event_id: gcalEventId || (alreadySynced ? opCtx.calendar_event_id : null),
        error_detail: alreadySynced ? null : errorDetail,
        was_already_synced: alreadySynced
    }
}];

// GCAL_UPDATE idempotency (finding #18):
// Repeated execution must converge to the desired appointment state.
// If update returns event with correct times → SUCCESS.
// Worker crash after GCal UPDATE but before DB SUCCESS:
//   On retry: UPDATE is called again with same data → idempotent (same result).

const result = $input.first()?.json || {};
let opCtx = {};

try {
    const claimItems = $('Postgres_Claim_Pending_Ops').all();
    const pi = $input.first()?.pairedItem;
    const piIdx = (pi && typeof pi.item === 'number') ? pi.item : (typeof pi === 'number' ? pi : 0);
    const routeItems = $('Route_Operation_Type').all();
    if (routeItems[piIdx]) {
        const rpi = routeItems[piIdx]?.pairedItem;
        const rpiIdx = (rpi && typeof rpi.item === 'number') ? rpi.item : (typeof rpi === 'number' ? rpi : piIdx);
        opCtx = claimItems[rpiIdx]?.json || claimItems[0]?.json || {};
    } else {
        opCtx = claimItems[0]?.json || {};
    }
} catch(e) {
    opCtx = $('Postgres_Claim_Pending_Ops').first()?.json || {};
}

// 404 on UPDATE = event was deleted externally (stale event_id)
// Treat as soft-failure: log, mark PERMANENTLY_FAILED, do not retry (no event to update)
const statusCode = result.statusCode || (result.error?.code) || 0;
const isNotFound = statusCode === 404 || (result.error && result.error.code === 404);
const hasError = Boolean(result.error || (statusCode >= 400));

let success, errorDetail;
if (isNotFound) {
    // Stale event ID; the Calendar event no longer exists.
    // Queue a GCAL_CREATE instead (handled by reconciliation, not here).
    success = false;
    errorDetail = 'EVENT_NOT_FOUND: Calendar event ' + (opCtx.calendar_event_id || 'unknown') + ' no longer exists. Stale event_id.';
} else {
    success = Boolean(result.id && !result.error && !(statusCode >= 400));
    errorDetail = result.error ? JSON.stringify(result.error) : (hasError ? 'HTTP_' + statusCode : null);
}

return [{
    json: {
        operation_id: opCtx.operation_id,
        appointment_id: opCtx.appointment_id,
        operation_type: opCtx.operation_type,
        attempt_count: opCtx.attempt_count,
        max_attempts: opCtx.max_attempts,
        calendar_event_id: opCtx.calendar_event_id,
        idempotency_key: opCtx.idempotency_key,
        success: success,
        gcal_event_id: success ? (result.id || opCtx.calendar_event_id) : null,
        error_detail: errorDetail,
        was_not_found: isNotFound
    }
}];

// GCAL_DELETE idempotency (finding #19):
// The desired end state is: Calendar event does NOT exist.
// HTTP 404 means the event is already gone → desired state achieved → SUCCESS.
// HTTP 410 (Gone) also means already deleted → SUCCESS.
// Any other HTTP error → FAILED → retry.

const result = $input.first()?.json || {};
let opCtx = {};

try {
    const claimItems = $('Postgres_Claim_Pending_Ops').all();
    const pi = $input.first()?.pairedItem;
    const piIdx = (pi && typeof pi.item === 'number') ? pi.item : (typeof pi === 'number' ? pi : 0);
    const routeItems = $('Route_Operation_Type').all();
    if (routeItems[piIdx]) {
        const rpi = routeItems[piIdx]?.pairedItem;
        const rpiIdx = (rpi && typeof rpi.item === 'number') ? rpi.item : (typeof rpi === 'number' ? rpi : piIdx);
        opCtx = claimItems[rpiIdx]?.json || claimItems[0]?.json || {};
    } else {
        opCtx = claimItems[0]?.json || {};
    }
} catch(e) {
    opCtx = $('Postgres_Claim_Pending_Ops').first()?.json || {};
}

// 204 = success (GCal returns empty body on delete)
// 404 = already deleted (idempotent success)
// 410 = gone (idempotent success)
const statusCode = result.statusCode || (result.error?.code) || 0;
const isNotFound = statusCode === 404 || statusCode === 410 ||
    (result.error && (result.error.code === 404 || result.error.code === 410));
const hasError = Boolean(result.error || (statusCode >= 400 && statusCode !== 404 && statusCode !== 410));
const success = !hasError || isNotFound;

const errorDetail = hasError && !isNotFound
    ? (result.error ? JSON.stringify(result.error) : 'HTTP_' + statusCode)
    : null;

return [{
    json: {
        operation_id: opCtx.operation_id,
        appointment_id: opCtx.appointment_id,
        operation_type: opCtx.operation_type,
        attempt_count: opCtx.attempt_count,
        max_attempts: opCtx.max_attempts,
        calendar_event_id: opCtx.calendar_event_id,
        idempotency_key: opCtx.idempotency_key,
        // After DELETE success: clear calendar_event_id in appointments table
        success: success,
        gcal_event_id: null,  // DELETE success = no event_id
        error_detail: errorDetail,
        was_not_found: isNotFound
    }
}];

// Idempotency check for GCAL_CREATE (finding #16, #17)
// The architecture problem being solved:
//   1. Calendar Worker calls GCal CREATE → succeeds
//   2. Worker crashes before marking operation SUCCESS in DB
//   3. Worker retries → would create DUPLICATE Calendar event
//
// Solution: deterministic idempotency_key stored in the GCal event's
// extendedProperties. On retry, search GCal for this key first.
// If found: use existing event_id (no new event created).
// If not found: create new event WITH this key in extendedProperties.
//
// The GCal CREATE node below sets extendedProperties.private.idempotencyKey.
// The GCal search (advisory, if needed) would look for this property.
// For simplicity in n8n, we use the GCal event description to embed the key
// (GCal API privateExtendedProperty search requires special OAuth scope).
// Instead, we store appointment_id in the event, and the Postgres_Mark_Op_Success
// does a "check before update" to handle the case where event_id already matches.

const item = $input.first()?.json || {};

// Generate deterministic idempotency key for this CREATE operation
const idempotencyKey = item.idempotency_key || (item.appointment_id + ':GCAL_CREATE');

// The event summary will embed the appointment_id for reconciliation
const eventSummary = `${item.customer_name} - ${item.service} with ${item.doctor_name}`;
const eventDescription = [
  `Appointment ID: ${item.appointment_id}`,
  `Service: ${item.service}`,
  `Patient: ${item.customer_name}`,
  `Source: ${item.appointment_source || 'SYSTEM'}`,
  `idempotencyKey: ${idempotencyKey}`
].join('\n');

return [{
  json: {
    ...item,
    idempotency_key: idempotencyKey,
    gcal_event_summary: eventSummary,
    gcal_event_description: eventDescription
  }
}];
